package com.muthumol.player.dummy;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.media3.common.*;import java.util.*;import org.json.*;
/** TV-only actions share the live player. Subtitle controls are owned by PlayerActivity. */
@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
final class TvPlayerTools {
 final PlayerActivity a;final TvLibrary library;long sleepAt,loopA=-1,loopB=-1,undo=-1,undoUntil;boolean locked,undoing;long held;Dialog nextDialog;int nextSeconds;final Handler ui=new Handler(Looper.getMainLooper());
 TvPlayerTools(PlayerActivity activity){a=activity;library=new TvLibrary(a);library.remember(a.movie());}
 void choose(String title,String[] entries,java.util.function.IntConsumer action){Ui.menu(a,title,entries,action);}
 void menu(){if(a.player==null)return;choose("Playback options",new String[]{"Audio & clear dialogue","Playback speed · "+a.player.getPlaybackParameters().speed+"×","Episodes / next / previous","Go to time","Undo last seek","Bookmarks","A–B repeat · "+(loopA<0?"set A":loopB<0?"set B":"clear"),"Chapters","Frame step (paused)","Picture shape","Sleep timer","Remote lock · hold OK to unlock","Watch later · "+library.marked(a.movie(),"later"),"Mark watched / unwatched","Skip silence · "+a.player.getSkipSilenceEnabled(),"Download for offline","Picture in picture","Playback details","Open offline copy in another player"},n->{switch(n){case 0:audioMenu();break;case 1:speed();break;case 2:episodes();break;case 3:time();break;case 4:undo();break;case 5:bookmarks();break;case 6:if(loopA<0)loopA=a.player.getCurrentPosition();else if(loopB<0){long p=a.player.getCurrentPosition();if(p>loopA+500)loopB=p;else toast("B must be after A");}else loopA=loopB=-1;break;case 7:chapters();break;case 8:frame();break;case 9:a.aspectRatio();break;case 10:sleep();break;case 11:locked=true;a.view.hideController();toast("Remote locked. Hold OK for 2 seconds to unlock.");break;case 12:library.toggle(a.movie(),"later");toast("Watch later updated");break;case 13:library.toggle(a.movie(),"watched");toast("Watched status updated");break;case 14:boolean on=!a.player.getSkipSilenceEnabled();a.player.setSkipSilenceEnabled(on);a.prefs.edit().putBoolean("tvSkipSilence",on).apply();break;case 15:OfflineDownloads.get(a).add(a.movie());toast("Download added. Status is in Home → Downloads.");break;case 16:pip();break;case 18:OfflineDownloads.get(a).external(a,a.movie());break;case 17:details();}}
 );}
 void audioMenu(){choose("Sound",new String[]{"Audio tracks","Sound profile · "+new String[]{"Original","Clear Dialogue","Clear Dialogue Strong","Night"}[a.prefs.getInt("tvAudioMode",1)],"Volume boost · "+a.boost+"%","Output · "+(a.stereo?"TV speakers / stereo":"Multichannel PCM")},n->{if(n==0)a.audioMenu();if(n==1)choose("Sound profile",new String[]{"Original","Clear Dialogue","Clear Dialogue Strong","Night"},x->{a.prefs.edit().putInt("tvAudioMode",x).apply();restart();});if(n==2)choose("Volume boost",new String[]{"100%","125%","150%","175%","200%","250%","300%"},x->{a.boost=new int[]{100,125,150,175,200,250,300}[x];a.prefs.edit().putInt("boost",a.boost).apply();a.applyBoost(0);});if(n==3)choose("Audio output",new String[]{"TV speakers / stereo","Multichannel PCM · receiver must support it"},x->{a.stereo=x==0;a.prefs.edit().putBoolean("stereo",a.stereo).apply();restart();});});}
 void restart(){if(a.player==null)return;a.resumePosition=a.player.getCurrentPosition();a.resumePlaying=a.player.getPlayWhenReady();a.savePosition();a.release();a.start();}
 void speed(){String[] names={"0.25×","0.5×","0.75×","1×","1.25×","1.5×","1.75×","2×","3×","4×","Fine adjustment"};choose("Playback speed",names,n->{if(n==10){EditText input=Ui.input(a,"Speed 0.25–4.0",false);input.setInputType(8194);input.setText(""+a.player.getPlaybackParameters().speed);Ui.dialog(a).setTitle("Playback speed").setView(input).setPositiveButton("Apply",(d,w)->{try{setSpeed(Float.parseFloat(input.getText().toString()));}catch(Exception e){toast("Enter a speed from 0.25 to 4");}}).setNegativeButton("Cancel",null).show();}else setSpeed(new float[]{.25f,.5f,.75f,1,1.25f,1.5f,1.75f,2,3,4}[n]);});}
 void setSpeed(float speed){if(!Float.isFinite(speed)||speed<.25f||speed>4){toast("Use 0.25–4.0");return;}a.player.setPlaybackSpeed(speed);a.prefs.edit().putFloat("tvSpeed",speed).apply();}
 void time(){EditText input=Ui.input(a,"HH:MM:SS or MM:SS",false);input.setText(CinemaInfo.time(a.player.getCurrentPosition()));Ui.dialog(a).setTitle("Go to time").setView(input).setPositiveButton("Go",(d,w)->{try{long t=parseTime(input.getText().toString());long duration=a.player.getDuration();a.player.seekTo(duration>0?Math.min(duration,t):t);}catch(Exception e){toast("Enter a valid time");}}).setNegativeButton("Cancel",null).show();}
 static long parseTime(String text){String[] bits=text.trim().split(":");if(bits.length<1||bits.length>3)throw new IllegalArgumentException();long s=0;for(String bit:bits){long n=Long.parseLong(bit);if(n<0||n>9999)throw new IllegalArgumentException();s=Math.addExact(Math.multiplyExact(s,60),n);}return Math.multiplyExact(s,1000);}
 void seeked(long from,long to,int reason){if(reason!=Player.DISCONTINUITY_REASON_SEEK)return;if(!undoing&&Math.abs(to-from)>=60000){undo=from;undoUntil=SystemClock.elapsedRealtime()+15000;}undoing=false;}
 void undo(){if(undo<0||SystemClock.elapsedRealtime()>undoUntil){toast("No recent large seek to undo");return;}undoing=true;a.player.seekTo(undo);undo=-1;}
 JSONArray marks(){try{return new JSONArray(a.prefs.getString(a.movieKey("tvBookmarks"),"[]"));}catch(Exception e){return new JSONArray();}}
 void bookmarks(){JSONArray marks=marks();String[] labels=new String[marks.length()+1];labels[0]="+ Bookmark current moment";for(int i=0;i<marks.length();i++){JSONObject m=marks.optJSONObject(i);labels[i+1]=m==null?"Invalid bookmark":CinemaInfo.time(m.optLong("time"))+" · "+m.optString("note");}choose("Bookmarks",labels,n->{if(n==0){long at=a.player.getCurrentPosition();EditText note=Ui.input(a,"Optional note",false);Ui.dialog(a).setTitle("Bookmark · "+CinemaInfo.time(at)).setView(note).setPositiveButton("Save",(d,w)->{try{JSONArray arr=marks();if(arr.length()>=200){toast("200 bookmark limit per video");return;}arr.put(new JSONObject().put("time",at).put("note",note.getText().toString()));a.prefs.edit().putString(a.movieKey("tvBookmarks"),arr.toString()).apply();}catch(Exception ignored){}}).setNegativeButton("Cancel",null).show();}else {JSONObject m=marks.optJSONObject(n-1);if(m==null)return;choose("Bookmark",new String[]{"Play from here","Delete"},x->{if(x==0)a.player.seekTo(m.optLong("time"));else {JSONArray keep=new JSONArray();for(int i=0;i<marks.length();i++)if(i!=n-1)keep.put(marks.opt(i));a.prefs.edit().putString(a.movieKey("tvBookmarks"),keep.toString()).apply();}});}});}
 void neighbour(int direction){Movie next=TvLibrary.neighbour(a.items,a.movie(),direction);if(next==null)toast("No "+(direction<0?"previous":"next")+" episode found");else WatchSync.get(a).beforePlay(()->play(next));}
 void episodes(){List<Movie> movies=TvLibrary.episodes(a.items,a.movie());if(movies.isEmpty()){toast("No neighbouring episodes in the loaded library");return;}String[] names=new String[movies.size()];for(int i=0;i<names.length;i++)names[i]=MediaTitle.parse(movies.get(i).title).display();choose("Episodes",names,n->play(movies.get(n)));}
 void play(Movie movie){a.savePosition();a.release();a.subtitleUri=null;a.subtitleMime=null;a.appliedAutoSubtitle="";a.session.selectMovie(movie);int selected=-1;for(int i=0;i<a.items.size();i++)if(a.items.get(i).cacheIdentity().equals(movie.cacheIdentity()))selected=i;if(selected<0){a.items.add(movie);selected=a.items.size()-1;}a.index=selected;a.streamStats=a.session.stats;a.resumePosition=movie.savedPosition(a);a.resumePlaying=true;loopA=loopB=-1;a.restoreMovieSettings();a.autoSubtitleBeforeStart();a.start();library.remember(movie);}
 void ended(){library.remember(a.movie());if(!library.marked(a.movie(),"watched"))library.toggle(a.movie(),"watched");Movie next=TvLibrary.neighbour(a.items,a.movie(),1);if(next==null||!a.prefs.getBoolean("tvAutoplay",true))return;nextSeconds=10;nextDialog=Ui.dialog(a).setTitle("Next episode").setMessage(MediaTitle.parse(next.title).display()).setPositiveButton("Play now",(d,w)->play(next)).setNegativeButton("Cancel",(d,w)->ui.removeCallbacksAndMessages(null)).show();Runnable countdown=new Runnable(){public void run(){if(nextDialog==null||!nextDialog.isShowing())return;if(--nextSeconds<=0){nextDialog.dismiss();play(next);}else{nextDialog.setTitle("Next episode in "+nextSeconds+"s");ui.postDelayed(this,1000);}}};ui.postDelayed(countdown,1000);}
 void sleep(){choose("Sleep timer",new String[]{"Off","15 minutes","30 minutes","45 minutes","60 minutes","90 minutes","End of current video"},n->{if(n==0)sleepAt=0;else if(n==6){a.prefs.edit().putBoolean("tvAutoplay",false).apply();toast("Autoplay disabled; playback stops at the end");}else sleepAt=SystemClock.elapsedRealtime()+new int[]{0,15,30,45,60,90}[n]*60000L;});}
 void tick(){if(a.player==null)return;if(sleepAt>0&&SystemClock.elapsedRealtime()>=sleepAt){sleepAt=0;a.player.pause();toast("Sleep timer finished");}if(loopA>=0&&loopB>loopA&&a.player.getCurrentPosition()>=loopB)a.player.seekTo(loopA);if(a.controlsVisible&&a.info!=null){long speed=a.streamStats.throughputBits()/8,buffer=a.player.getTotalBufferedDuration();a.info.setText(String.format(Locale.US,"%.2f MB/s   ·   Buffer %s   ·   %s",speed/1048576.0,CinemaInfo.time(buffer),a.decoder));a.info.setVisibility(View.VISIBLE);}}
 void chapters(){List<Chapter> list=chapterList();if(list.isEmpty()){toast("This file exposes no chapter metadata");return;}String[] names=new String[list.size()];for(int i=0;i<names.length;i++)names[i]=CinemaInfo.time(list.get(i).time)+" · "+list.get(i).title;choose("Chapters",names,n->a.player.seekTo(list.get(n).time));}
 static final class Chapter{long time;String title;Chapter(long t,String s){time=t;title=s;}}
 List<Chapter> chapterList(){List<Chapter> list=new ArrayList<>();for(Tracks.Group group:a.player.getCurrentTracks().getGroups())for(int i=0;i<group.length;i++){Metadata md=group.getTrackFormat(i).metadata;if(md==null)continue;for(int j=0;j<md.length();j++){Metadata.Entry entry=md.get(j);if(entry instanceof androidx.media3.extractor.metadata.id3.ChapterFrame){androidx.media3.extractor.metadata.id3.ChapterFrame c=(androidx.media3.extractor.metadata.id3.ChapterFrame)entry;list.add(new Chapter(c.startTimeMs,c.chapterId));}}}list.sort(Comparator.comparingLong(c->c.time));return list;}
 void frame(){a.player.pause();Format format=a.player.getVideoFormat();float fps=format!=null&&format.frameRate>0?format.frameRate:25;choose("Frame step · seek precision depends on format",new String[]{"Previous frame","Next frame"},n->{a.player.setSeekParameters(androidx.media3.exoplayer.SeekParameters.EXACT);a.player.seekTo(Math.max(0,a.player.getCurrentPosition()+(n==0?-1:1)*Math.round(1000/fps)));});}
 boolean key(KeyEvent e){if(!locked)return false;int code=e.getKeyCode();if(code==KeyEvent.KEYCODE_VOLUME_UP||code==KeyEvent.KEYCODE_VOLUME_DOWN||code==KeyEvent.KEYCODE_VOLUME_MUTE)return false;if(code==KeyEvent.KEYCODE_DPAD_CENTER||code==KeyEvent.KEYCODE_ENTER){if(e.getAction()==KeyEvent.ACTION_DOWN){if(e.getRepeatCount()==0){held=SystemClock.elapsedRealtime();ui.postDelayed(unlockTask,2000);}if(SystemClock.elapsedRealtime()-held>=2000){locked=false;toast("Remote unlocked");a.showRemoteControls();}}else {held=0;ui.removeCallbacks(unlockTask);}}return true;}
 final Runnable unlockTask=this::unlock;
 void unlock(){if(locked){locked=false;toast("Remote unlocked");a.showRemoteControls();}}
 void hidden(){ui.removeCallbacksAndMessages(null);if(nextDialog!=null){nextDialog.dismiss();nextDialog=null;}}
 void pip(){if(Build.VERSION.SDK_INT>=26&&a.getPackageManager().hasSystemFeature("android.software.picture_in_picture")){try{a.enterPictureInPictureMode(new PictureInPictureParams.Builder().setAspectRatio(new android.util.Rational(16,9)).build());}catch(Exception e){toast("Picture in picture is unavailable");}}else toast("Picture in picture is not supported by this TV");}
 void details(){String details="Video: "+a.decoder+"\nAudio: "+a.audioDecoder+"\nSpeed: "+a.player.getPlaybackParameters().speed+"×\nBuffered: "+CinemaInfo.time(a.player.getTotalBufferedDuration())+"\nCache: "+MainActivity.size(a.streamStats.cachedBytes())+"\nStalls: "+a.streamStats.stalls+"\n"+a.movie().details();Ui.message(a,"Playback details",details);}
 void toast(String text){Toast.makeText(a,text,Toast.LENGTH_SHORT).show();}
 void close(){hidden();}
}
